SELECT '1. ensure_trip_share_slug 含 TRIP_OWNER_GUARD_V1 且只出現一組' AS item, (SELECT (length(p.prosrc) - length(replace(p.prosrc, 'TRIP_OWNER_GUARD_V1', ''))) / length('TRIP_OWNER_GUARD_V1') = 2 FROM pg_proc p WHERE p.oid = to_regprocedure('public.ensure_trip_share_slug(uuid)')) AS ok
UNION ALL SELECT '2. ensure_trip_share_slug 去掉檢查段後指紋＝6743b0826daf26406875603a277a41d4', (SELECT md5(regexp_replace(replace(p.prosrc, E'\r', ''), E'\n  -- TRIP_OWNER_GUARD_V1 BEGIN.*-- TRIP_OWNER_GUARD_V1 END', '')) = '6743b0826daf26406875603a277a41d4' FROM pg_proc p WHERE p.oid = to_regprocedure('public.ensure_trip_share_slug(uuid)'))
UNION ALL SELECT '3. 檢查段內容：auth.uid() 為 null 或非 owner_id 即 42501', (SELECT position('IF auth.uid() IS NULL OR NOT EXISTS (SELECT 1 FROM public.trips t WHERE t.id = p_trip_id AND t.owner_id = auth.uid()) THEN' IN p.prosrc) > 0 AND position('USING ERRCODE = ''42501''' IN p.prosrc) > 0 FROM pg_proc p WHERE p.oid = to_regprocedure('public.ensure_trip_share_slug(uuid)'))
UNION ALL SELECT '4. ensure_trip_share_slug 屬性不變：SECURITY DEFINER、plpgsql、RETURNS text、search_path=public', (SELECT p.prosecdef AND l.lanname = 'plpgsql' AND p.prorettype = 'text'::regtype AND p.proconfig = ARRAY['search_path=public'] FROM pg_proc p JOIN pg_language l ON l.oid = p.prolang WHERE p.oid = to_regprocedure('public.ensure_trip_share_slug(uuid)'))
UNION ALL SELECT '5. ensure_trip_share_slug 授權：anon 不可、無 PUBLIC；authenticated、service_role 可', (SELECT NOT has_function_privilege('anon', p.oid, 'EXECUTE') AND NOT EXISTS (SELECT 1 FROM aclexplode(p.proacl) a WHERE a.grantee = 0) AND has_function_privilege('authenticated', p.oid, 'EXECUTE') AND has_function_privilege('service_role', p.oid, 'EXECUTE') FROM pg_proc p WHERE p.oid = to_regprocedure('public.ensure_trip_share_slug(uuid)'))
UNION ALL SELECT '6. _hotelnabe_enqueue_days 指紋不變＝8e9c59faaf944996252177d8a0071ab6', (SELECT md5(replace(p.prosrc, E'\r', '')) = '8e9c59faaf944996252177d8a0071ab6' FROM pg_proc p WHERE p.oid = to_regprocedure('public._hotelnabe_enqueue_days(uuid, uuid, date, date, public.hotelnabe_ari_push_reason)'))
UNION ALL SELECT '7. _hotelnabe_enqueue_days 授權：anon、authenticated 不可、無 PUBLIC；service_role、postgres 可', (SELECT NOT has_function_privilege('anon', p.oid, 'EXECUTE') AND NOT has_function_privilege('authenticated', p.oid, 'EXECUTE') AND NOT EXISTS (SELECT 1 FROM aclexplode(p.proacl) a WHERE a.grantee = 0) AND has_function_privilege('service_role', p.oid, 'EXECUTE') AND has_function_privilege('postgres', p.oid, 'EXECUTE') FROM pg_proc p WHERE p.oid = to_regprocedure('public._hotelnabe_enqueue_days(uuid, uuid, date, date, public.hotelnabe_ari_push_reason)'))
UNION ALL SELECT '8. 3 支 hotelnabe 觸發器函式仍為 SECURITY DEFINER，且其擁有者可執行 _hotelnabe_enqueue_days', (SELECT count(*) = 3 AND bool_and(p.prosecdef) AND bool_and(has_function_privilege(p.proowner, to_regprocedure('public._hotelnabe_enqueue_days(uuid, uuid, date, date, public.hotelnabe_ari_push_reason)'), 'EXECUTE')) FROM pg_proc p WHERE p.pronamespace = 'public'::regnamespace AND p.proname IN ('fn_hotelnabe_enqueue_from_order', 'fn_hotelnabe_enqueue_from_order_rooms', 'fn_hotelnabe_enqueue_from_rip'))
UNION ALL SELECT '9. 其他授權對象未被變動：兩支函式仍保有 sandbox_exec_* 的執行權（正式庫原有）', (SELECT count(*) = 2 FROM pg_proc p WHERE p.oid IN (to_regprocedure('public.ensure_trip_share_slug(uuid)'), to_regprocedure('public._hotelnabe_enqueue_days(uuid, uuid, date, date, public.hotelnabe_ari_push_reason)')) AND EXISTS (SELECT 1 FROM aclexplode(p.proacl) a JOIN pg_roles r ON r.oid = a.grantee WHERE r.rolname LIKE 'sandbox_exec_%' AND a.privilege_type = 'EXECUTE'));

SELECT p.oid::regprocedure::text AS func, COALESCE(p.proacl::text, 'NULL') AS proacl_after, md5(replace(p.prosrc, E'\r', '')) AS fp_after, has_function_privilege('anon', p.oid, 'EXECUTE') AS anon_exec, has_function_privilege('authenticated', p.oid, 'EXECUTE') AS auth_exec, has_function_privilege('service_role', p.oid, 'EXECUTE') AS service_exec
FROM pg_proc p
WHERE p.oid IN (to_regprocedure('public.ensure_trip_share_slug(uuid)'), to_regprocedure('public._hotelnabe_enqueue_days(uuid, uuid, date, date, public.hotelnabe_ari_push_reason)'))
ORDER BY 1;
